import { getPublicJson } from '@/service/http/client';

const GITHUB_REPO_API = 'https://api.github.com/repos/weifuwan/yak-ops';
const RELEASE_PAGE_SIZE = 100;

interface GitHubRepository {
  stargazers_count: number;
  forks_count: number;
}

interface GitHubRelease {
  draft: boolean;
  prerelease: boolean;
  assets: Array<{ name: string; download_count: number }>;
}

export interface GitHubProjectStats {
  stars: number;
  forks: number;
  downloads: number;
}

/**
 * GitHub download counts only include actual versioned distribution archives.
 * Checksums, release evidence, autogenerated source archives and Docker pulls
 * are intentionally excluded. Page through releases to avoid a partial total.
 */
async function fetchPackageDownloads(signal: AbortSignal): Promise<number> {
  let downloads = 0;
  let page = 1;

  while (true) {
    const releases = await getPublicJson<GitHubRelease[]>(
      `${GITHUB_REPO_API}/releases?per_page=${RELEASE_PAGE_SIZE}&page=${page}`,
      { signal },
    );

    for (const release of releases) {
      if (release.draft || release.prerelease) continue;

      for (const asset of release.assets) {
        if (/^yak-ops-\d+\.\d+\.\d+\.tar\.gz$/.test(asset.name)) {
          downloads += asset.download_count;
        }
      }
    }

    if (releases.length < RELEASE_PAGE_SIZE) return downloads;
    page += 1;
  }
}

export async function fetchGitHubProjectStats(signal: AbortSignal): Promise<GitHubProjectStats> {
  const [repository, downloads] = await Promise.all([
    getPublicJson<GitHubRepository>(GITHUB_REPO_API, { signal }),
    fetchPackageDownloads(signal),
  ]);

  return {
    stars: repository.stargazers_count,
    forks: repository.forks_count,
    downloads,
  };
}
